    11  /* this code supports:
    12   * reading:
    13   *     uncompressed and run length encoded indexed, grey and color tga files.
    14   *     image types 1, 2, 3, 9, 10 and 11.
    15   *     only RGB color maps with no more than 256 colors.
    16   *     pixel formats 8, 16, 24 and 32.
    17   * writing:
    18   *     uncompressed true color tga files
    19   */
    20
    21  #include "tga_p.h"
    22
    23  #include <assert.h>
    24
    25  #include <QImage>
    26  #include <QDataStream>
    27  #include <QDebug>
    28
    29  typedef quint32 uint;
    30  typedef quint16 ushort;
    31  typedef quint8 uchar;
    32
    33  namespace   // Private.
    34  {
    35
    36  // Header format of saved files.
    37  uchar targaMagic[12] = { 0, 0, 2, 0, 0, 0, 0, 0, 0, 0, 0, 0 };
    38
    39  enum TGAType {
    40      TGA_TYPE_INDEXED        = 1,
    41      TGA_TYPE_RGB            = 2,
    42      TGA_TYPE_GREY           = 3,
    43      TGA_TYPE_RLE_INDEXED    = 9,
    44      TGA_TYPE_RLE_RGB        = 10,
    45      TGA_TYPE_RLE_GREY       = 11
    46  };
    47
    48  #define TGA_INTERLEAVE_MASK 0xc0
    49  #define TGA_INTERLEAVE_NONE 0x00
    50  #define TGA_INTERLEAVE_2WAY 0x40
    51  #define TGA_INTERLEAVE_4WAY 0x80
    52
    53  #define TGA_ORIGIN_MASK     0x30
    54  #define TGA_ORIGIN_LEFT     0x00
    55  #define TGA_ORIGIN_RIGHT    0x10
    56  #define TGA_ORIGIN_LOWER    0x00
    57  #define TGA_ORIGIN_UPPER    0x20
    58
    59  /** Tga Header. */
    60  struct TgaHeader {
    61      uchar id_length;
    62      uchar colormap_type;
    63      uchar image_type;
    64      ushort colormap_index;
    65      ushort colormap_length;
    66      uchar colormap_size;
    67      ushort x_origin;
    68      ushort y_origin;
    69      ushort width;
    70      ushort height;
    71      uchar pixel_size;
    72      uchar flags;
    73
    74      enum { SIZE = 18 }; // const static int SIZE = 18;
    75  };
    76
    77  static QDataStream &operator>> (QDataStream &s, TgaHeader &head)
    78  {
    79      s >> head.id_length;
    80      s >> head.colormap_type;
    81      s >> head.image_type;
    82      s >> head.colormap_index;
    83      s >> head.colormap_length;
    84      s >> head.colormap_size;
    85      s >> head.x_origin;
    86      s >> head.y_origin;
    87      s >> head.width;
    88      s >> head.height;
    89      s >> head.pixel_size;
    90      s >> head.flags;
    91      /*qDebug() << "id_length: " << head.id_length << " - colormap_type: " << head.colormap_type << " - image_type: " << head.image_type;
    92      qDebug() << "colormap_index: " << head.colormap_index << " - colormap_length: " << head.colormap_length << " - colormap_size: " << head.colormap_size;
    93      qDebug() << "x_origin: " << head.x_origin << " - y_origin: " << head.y_origin << " - width:" << head.width << " - height:" << head.height << " - pixelsize: " << head.pixel_size << " - flags: " << head.flags;*/
    94      return s;
    95  }
    96
    97  static bool IsSupported(const TgaHeader &head)
    98  {
    99      if (head.image_type != TGA_TYPE_INDEXED &&
   100              head.image_type != TGA_TYPE_RGB &&
   101              head.image_type != TGA_TYPE_GREY &&
   102              head.image_type != TGA_TYPE_RLE_INDEXED &&
   103              head.image_type != TGA_TYPE_RLE_RGB &&
   104              head.image_type != TGA_TYPE_RLE_GREY) {
   105          return false;
   106      }
   107      if (head.image_type == TGA_TYPE_INDEXED ||
   108              head.image_type == TGA_TYPE_RLE_INDEXED) {
   109          if (head.colormap_length > 256 || head.colormap_size != 24 || head.colormap_type != 1) {
   110              return false;
   111          }
   112      }
   113      if (head.image_type == TGA_TYPE_RGB ||
   114              head.image_type == TGA_TYPE_GREY ||
   115              head.image_type == TGA_TYPE_RLE_RGB ||
   116              head.image_type == TGA_TYPE_RLE_GREY) {
   117          if (head.colormap_type != 0) {
   118              return false;
   119          }
   120      }
   121      if (head.width == 0 || head.height == 0) {
   122          return false;
   123      }
   124      if (head.pixel_size != 8 && head.pixel_size != 16 &&
   125              head.pixel_size != 24 && head.pixel_size != 32) {
   126          return false;
   127      }
   128      return true;
   129  }
   130
   131  struct Color555 {
   132      ushort b : 5;
   133      ushort g : 5;
   134      ushort r : 5;
   135  };
   136
   137  struct TgaHeaderInfo {
   138      bool rle;
   139      bool pal;
   140      bool rgb;
   141      bool grey;
   142
   143      TgaHeaderInfo(const TgaHeader &tga) : rle(false), pal(false), rgb(false), grey(false)
   144      {
   145          switch (tga.image_type) {
   146          case TGA_TYPE_RLE_INDEXED:
   147              rle = true;
   148          Q_FALLTHROUGH();
   149          // no break is intended!
   150          case TGA_TYPE_INDEXED:
   151              pal = true;
   152              break;
   153
   154          case TGA_TYPE_RLE_RGB:
   155              rle = true;
   156          Q_FALLTHROUGH();
   157          // no break is intended!
   158          case TGA_TYPE_RGB:
   159              rgb = true;
   160              break;
   161
   162          case TGA_TYPE_RLE_GREY:
   163              rle = true;
   164          Q_FALLTHROUGH();
   165          // no break is intended!
   166          case TGA_TYPE_GREY:
   167              grey = true;
   168              break;
   169
   170          default:
   171              // Error, unknown image type.
   172              break;
   173          }
   174      }
   175  };
   176
   177  static bool LoadTGA(QDataStream &s, const TgaHeader &tga, QImage &img)
   178  {
   179      // Create image.
   180      img = QImage(tga.width, tga.height, QImage::Format_RGB32);
   181
   182      TgaHeaderInfo info(tga);
   183
   184      // Bits 0-3 are the numbers of alpha bits (can be zero!)
   185      const int numAlphaBits = tga.flags & 0xf;
   186      // However alpha exists only in the 32 bit format.
   187      if ((tga.pixel_size == 32) && (tga.flags & 0xf)) {
   188          img = QImage(tga.width, tga.height, QImage::Format_ARGB32);
   189
   190          if (numAlphaBits > 8) {
   191              return false;
   192          }
   193      }
   194
   195      uint pixel_size = (tga.pixel_size / 8);
   196      qint64 size = qint64(tga.width) * qint64(tga.height) * pixel_size;
   197
   198      if (size < 1) {
   199  //          qDebug() << "This TGA file is broken with size " << size;
   200          return false;
   201      }
   202
   203      // Read palette.
   204      char palette[768];
   205      if (info.pal) {
   206          // @todo Support palettes in other formats!
   207          const int size = 3 * tga.colormap_length;
   208          const int dataRead = s.readRawData(palette, size);
   209          if (dataRead < 0) {
   210              return false;
   211          }
   212          if (dataRead < size) {
   213              memset(&palette[dataRead], 0, size - dataRead);
   214          }
   215      }
   216
   217      // Allocate image.
   218      uchar *const image = reinterpret_cast<uchar*>(malloc(size));
   219      if (!image) {
   220          return false;
   221      }
   222
   223      bool valid = true;
   224
   225      if (info.rle) {
   226          // Decode image.
   227          char *dst = (char *)image;
   228          qint64 num = size;
   229
   230          while (num > 0) {
   231              if (s.atEnd()) {
   232                  valid = false;
   233                  break;
   234              }
   235
   236              // Get packet header.
   237              uchar c;
   238              s >> c;
   239
   240              uint count = (c & 0x7f) + 1;
   241              num -= count * pixel_size;
   242              if (num < 0) {
   243                  valid = false;
   244                  break;
   245              }
   246
   247              if (c & 0x80) {
   248                  // RLE pixels.
   249                  assert(pixel_size <= 8);
   250                  char pixel[8];
   251                  s.readRawData(pixel, pixel_size);
   252                  do {
   253                      memcpy(dst, pixel, pixel_size);
   254                      dst += pixel_size;
   255                  } while (--count);
   256              } else {
   257                  // Raw pixels.
   258                  count *= pixel_size;
   259                  s.readRawData(dst, count);
   260                  dst += count;

